        CultEvent.Random("lf14", StatId.LeaderFaith, new Question("측근이 당신의 신앙을 의심하는 말을 엿들었습니다. 복도 끝 문틈으로 목소리가 새어 나옵니다.\u001FYou overhear someone in your inner circle doubting your faith. Voices leak through a door ajar at the end of the hall.",
