        CultEvent.Random("lf15", StatId.LeaderFaith, new Question("폭풍우 치는 밤 교단 건물에 벼락이 떨어졌습니다. 지붕 한쪽이 불에 그을렸습니다.\u001FOn a stormy night, lightning strikes the cult's building. One side of the roof is scorched.",
