        CultEvent.Random("lf18", StatId.LeaderFaith, new Question("기도문을 새로 지어 보기로 했습니다. 컴퓨터 화면에는 썼다 지운 문장이 가득합니다.\u001FYou decide to write a new prayer. Your computer screen is full of sentences written and deleted.",
