        CultEvent.Conditional("cd31", c => c[StatId.Reputation].Value <= 250, new Question("동네 주민들이 교단 건물 앞에서 반대 시위를 벌입니다. 피켓이 담벼락에 줄지어 서 있습니다.\u001FLocals stage a protest outside the cult's building. Picket signs line the wall.",
