        CultEvent.Conditional("cd32", c => c[StatId.Reputation].Value <= 200, new Question("지역의 여러 종교 단체가 연합해 교단을 이단으로 규정했습니다.\u001FReligious groups across the region have united to brand the cult heretical.",
