        CultEvent.Conditional("cd38", c => c[StatId.Reputation].Value <= 300 && c[StatId.Followers].Value >= 30, new Question("신도들의 가족이 교단을 고소하겠다며 모였습니다. 교단 앞에서 가족들이 피켓을 들고 있습니다.\u001FFollowers' families gather, threatening to sue the cult. They hold picket signs outside the cult.",
