        CultEvent.Negative("ln01", c => c[StatId.LeaderFaith].Value <= 80, new Question("기도를 올려도 아무 응답이 없습니다. 몇 달째 신의 목소리는 끊겼고, 새벽마다 빈 방에 홀로 앉아 있습니다.\u001FYou pray, but there is no answer. God's voice has been silent for months, and every dawn you sit alone in an empty room.",
