        CultEvent.Negative("ln02", c => c[StatId.LeaderFaith].Value <= 80, new Question("설교 도중 갑자기 말문이 막혔습니다. 수십 개의 눈이 당신을 향해 있고, 어디까지 말했는지 떠오르지 않습니다.\u001FMid-sermon, the words suddenly fail you. Dozens of eyes are on you, and you can't recall where you left off.",
