        CultEvent.Negative("fn01", c => c[StatId.FollowerFaith].Value <= 80, new Question("집회에서 신도들이 기계적으로 입만 움직입니다. 눈빛에는 믿음이 없고 시계만 힐끔거립니다.\u001FAt the gathering, your followers mouth the words mechanically. There is no faith in their eyes; they keep glancing at the clock.",
