        CultEvent.Negative("fn02", c => c[StatId.FollowerFaith].Value <= 80, new Question("고참 신도 하나가 집회에서 공개적으로 교단을 떠나겠다고 선언했습니다. 그의 목소리가 강당에 울립니다.\u001FA veteran follower publicly announces at the gathering that he is leaving the cult. His voice rings through the hall.",
