        CultEvent.Negative("n_cm02", c => c[StatId.Communion].Value <= 1, new Question("접신을 시도하던 밤, 어둠 속에서 알 수 없는 공허한 울림이 들렸습니다. 눈을 뜨니 촛불이 모두 꺼져 있습니다.\u001FOn a night you attempt Communion, a hollow, unknowable resonance sounds in the dark. When you open your eyes, every candle is out.",
